#include <expected>
#include <iostream>
#include <limits>
#include <print>
#include <string>

std::expected<int, std::string> divide(int a, int b) {
    if (b == 0) {
        return std::unexpected("деление на ноль");
    }
    if (a == std::numeric_limits<int>::min() && b == -1) {
        return std::unexpected("переполнение");
    }
    return a / b;
}

int main() {
    int a, b;
    while (std::cin >> a >> b) {
        auto q = divide(a, b);
        if (q) {
            std::println("{} / {} = {}", a, b, *q);
        } else {
            std::println("{} / {}: ошибка: {}", a, b, q.error());
        }
    }
    return 0;
}

